import { readFile, realpath, stat } from "node:fs/promises";
import { resolve, sep } from "node:path";

/** @typedef {import('./types.js').Profile} Profile */
/** @typedef {import('./types.js').Lesson} Lesson */
/** @typedef {import('./types.js').Course} Course */

const ID = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;
const PROFILE_KEYS = [
  "schemaVersion",
  "id",
  "title",
  "technology",
  "version",
  "goal",
  "audience",
  "officialHosts",
  "sources",
  "curriculum",
];
const LESSON_KEYS = [
  "schemaVersion",
  "id",
  "title",
  "goal",
  "prerequisites",
  "explanation",
  "exercise",
  "sources",
  "slides",
];

/** @param {unknown} value @param {string[]} keys @param {string} at @returns {Record<string, unknown>} */
function object(value, keys, at) {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error(`ERR-01 ${at}: オブジェクトが必要です`);
  }
  const data = /** @type {Record<string, unknown>} */ (value);
  const actual = Object.keys(data);
  if (actual.length !== keys.length || actual.some((key) => !keys.includes(key))) {
    throw new Error(`ERR-01 ${at}: キーは ${keys.join(", ")} です`);
  }
  return data;
}

/** @param {unknown} value @param {string} at @param {boolean} [allowEmpty] @returns {string} */
function text(value, at, allowEmpty = false) {
  if (typeof value !== "string" || (!allowEmpty && !value.trim())) {
    throw new Error(`ERR-01 ${at}: 文字列が必要です`);
  }
  return value;
}

/** @param {unknown} value @param {string} at @param {boolean} [allowEmpty] @returns {unknown[]} */
function array(value, at, allowEmpty = false) {
  if (!Array.isArray(value) || (!allowEmpty && value.length === 0)) {
    throw new Error(`ERR-01 ${at}: 配列が必要です`);
  }
  return /** @type {unknown[]} */ (value);
}

/** @param {unknown} value @param {string} at @returns {string} */
function id(value, at) {
  const result = text(value, at);
  if (!ID.test(result)) {
    throw new Error(`NAM-01 ${at}: 英字始まりkebab-caseが必要です`);
  }
  return result;
}

/** @param {string[]} values @param {string} at @returns {void} */
function unique(values, at) {
  if (new Set(values).size !== values.length) {
    throw new Error(`NAM-01 ${at}: IDが重複しています`);
  }
}

/** @param {unknown} value @param {string} at @returns {void} */
function version(value, at) {
  if (/^(?:latest|stable|current|unknown|未確認|最新版)$/i.test(text(value, at).trim())) {
    throw new Error(`OPS-01 ${at}: 対象版を特定してください`);
  }
}

/** @param {Record<string, unknown>} data @param {string[]} fields @param {string} at @returns {void} */
function texts(data, fields, at) {
  for (const key of fields) {
    text(data[key], `${at}.${key}`);
  }
}

/** @param {unknown} value @returns {Profile} 検証済みプロフィールを返す。 */
export function parseProfile(value) {
  const data = object(value, PROFILE_KEYS, "profile");
  if (data.schemaVersion != 1) {
    throw new Error("ERR-01 schemaVersion: 1が必要です");
  }
  id(data.id, "profile.id");
  texts(data, ["title", "technology", "version", "goal", "audience"], "profile");
  version(data.version, "profile.version");
  const hosts = array(data.officialHosts, "officialHosts").map((host) => text(host, "host"));
  for (const host of hosts) {
    if (!/^[a-z0-9]+(?:[.-][a-z0-9]+)*\.[a-z]{2,}$/i.test(host)) {
      throw new Error("OPS-01 officialHosts: ホスト名だけを指定してください");
    }
  }
  const sourceIds = array(data.sources, "sources").map((item) => {
    const source = object(item, ["id", "title", "url", "version", "checkedAt"], "source");
    texts(source, ["title", "url", "version", "checkedAt"], "source");
    version(source.version, "source.version");
    const url = new URL(text(source.url, "source.url"));
    if (
      url.protocol !== "https:" ||
      url.username ||
      url.password ||
      url.port ||
      !hosts.includes(url.hostname)
    ) {
      throw new Error("OPS-01 source.url: 登録した公式hostのHTTPSが必要です");
    }
    const date = text(source.checkedAt, "source.checkedAt");
    if (
      !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
      Number.isNaN(Date.parse(date)) ||
      new Date(date).toISOString().slice(0, 10) !== date
    ) {
      throw new Error("OPS-01 checkedAt: 実在するYYYY-MM-DDが必要です");
    }
    return id(source.id, "source.id");
  });
  unique(sourceIds, "sources");
  /** @type {string[]} */
  const earlier = [];
  for (const item of array(data.curriculum, "curriculum")) {
    const unit = object(item, ["id", "title", "goal", "dependsOn"], "curriculum");
    const unitId = id(unit.id, "curriculum.id");
    texts(unit, ["title", "goal"], "curriculum");
    const dependencies = array(unit.dependsOn, "dependsOn", true).map((itemId) =>
      id(itemId, "dependsOn"),
    );
    unique(dependencies, "dependsOn");
    if (dependencies.some((itemId) => !earlier.includes(itemId))) {
      throw new Error("ERR-01 dependsOn: 先行する学習項目だけを参照できます");
    }
    earlier.push(unitId);
  }
  unique(earlier, "curriculum");
  return /** @type {Profile} */ (value);
}

/** @param {unknown} value @param {Profile} profile @param {string} curriculumId @returns {Lesson} */
export function parseLesson(value, profile, curriculumId) {
  const data = object(value, LESSON_KEYS, "lesson");
  const unit = profile.curriculum.find((item) => item.id === curriculumId);
  if (
    !unit ||
    data.id !== unit.id ||
    data.title !== unit.title ||
    data.goal !== unit.goal ||
    data.schemaVersion !== 1
  ) {
    throw new Error("ERR-01 lesson: curriculumのid/title/goalとschemaVersionを一致させてください");
  }
  array(data.prerequisites, "prerequisites").forEach((item) => text(item, "prerequisite"));
  for (const item of array(data.explanation, "explanation")) {
    const section = object(item, ["title", "body", "code", "output"], "explanation");
    texts(section, ["title", "body"], "explanation");
    text(section.code, "code", true);
    text(section.output, "output", true);
  }
  const exercise = object(data.exercise, ["prompt", "answer"], "exercise");
  texts(exercise, ["prompt", "answer"], "exercise");
  const refs = array(data.sources, "lesson.sources").map((item) => id(item, "source"));
  unique(refs, "lesson.sources");
  if (refs.some((ref) => !profile.sources.some((source) => source.id === ref))) {
    throw new Error("ERR-01 sources: 未登録の出典です");
  }
  const files = array(data.slides, "slides").map((item) => validateSlide(item));
  unique(files, "slides.file");
  return /** @type {Lesson} */ (value);
}

/** @param {unknown} item @returns {string} */
function validateSlide(item) {
  const slide = object(item, ["file", "title", "notes"], "slide");
  text(slide.title, "slide.title");
  const file = text(slide.file, "slide.file");
  if (!/^[a-z0-9][a-z0-9-]*\.html$/.test(file)) {
    throw new Error("OPS-02 slide.file: slides内のHTMLファイル名だけを許可します");
  }
  /** @type {string[]} */
  const ids = [];
  /** @type {string[]} */
  const targets = [];
  for (const itemNote of array(slide.notes, "notes")) {
    const note = object(itemNote, ["id", "target", "side", "title", "body"], "note");
    ids.push(id(note.id, "note.id"));
    targets.push(id(note.target, "note.target"));
    texts(note, ["title", "body"], "note");
    if (note.side !== "left" && note.side !== "right") {
      throw new Error("ERR-01 note.side: left/rightが必要です");
    }
  }
  unique(ids, "notes.id");
  unique(targets, "notes.target");
  return file;
}

/** @param {string} html @returns {{tag: string, attributes: Map<string, string>}[]} 静的スライドの実要素から属性を読む。 */
function elementsIn(html) {
  // コメントとraw text内のタグ風文字列はDOM要素にはならない。
  const content = html
    .replace(/<!--[\s\S]*?(?:-->|$)/g, "")
    .replace(/<(script|style|textarea|title)\b[^>]*>[\s\S]*?(?:<\/\1\s*>|$)/gi, "");
  const elements = [];
  const tags = /<([a-z][a-z0-9:-]*)\b((?:"[^"]*"|'[^']*'|[^'">])*)>/gi;
  const attributes = /([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'<>=`]+)))?/g;
  for (const match of content.matchAll(tags)) {
    const tag = match[1]?.toLowerCase();
    const values = new Map();
    for (const attribute of (match[2] ?? "").matchAll(attributes)) {
      const name = attribute[1]?.toLowerCase();
      if (!name) {
        continue;
      }
      if (values.has(name)) {
        throw new Error(`ERR-01 HTML属性 ${name} が同じ要素で重複しています`);
      }
      values.set(name, attribute[2] ?? attribute[3] ?? attribute[4] ?? "");
    }
    if (tag) {
      elements.push({ tag, attributes: values });
    }
  }
  return elements;
}

/** @param {string} base @param {string} leaf @returns {Promise<string>} */
async function within(base, leaf) {
  const basePath = await realpath(base);
  const fullPath = await realpath(resolve(basePath, leaf));
  if (!fullPath.startsWith(basePath + sep)) {
    throw new Error(`OPS-02 ${leaf}: 配置先の外を参照できません`);
  }
  return fullPath;
}

/** @param {string} courseDir @returns {Promise<Course>} 全学習項目と注目対象を検証する。 */
export async function readCourse(courseDir) {
  const profile = parseProfile(
    JSON.parse(await readFile(await within(courseDir, "profile.json"), "utf8")),
  );
  /** @type {Course['lessons']} */
  const lessons = [];
  for (const unit of profile.curriculum) {
    const lessonDir = await within(courseDir, `lessons/${unit.id}`);
    const lesson = parseLesson(
      JSON.parse(await readFile(await within(lessonDir, "lesson.json"), "utf8")),
      profile,
      unit.id,
    );
    const deckDir = await within(lessonDir, "deck");
    for (const required of ["deck.md", "theme.css", "index.html", "slides"]) {
      await stat(await within(deckDir, required));
    }
    for (const slide of lesson.slides) {
      const html = await readFile(await within(deckDir, `slides/${slide.file}`), "utf8");
      const elements = elementsIn(html);
      const roots = elements.filter(
        (element) =>
          element.tag === "article" &&
          (element.attributes.get("class") ?? "").split(/\s+/).includes("slide"),
      );
      if (roots.length !== 1) {
        throw new Error(`STR-01 ${unit.id}/${slide.file}: article.slideが必要です`);
      }
      for (const note of slide.notes) {
        const matches = elements.filter(
          (element) => element.attributes.get("data-learning-target") === note.target,
        );
        if (matches.length !== 1) {
          throw new Error(`NAM-01 ${unit.id}/${slide.file}: target ${note.target} は1箇所必要です`);
        }
      }
    }
    lessons.push({ lesson, deckDir });
  }
  return { profile, lessons };
}

/** @typedef {import('./types.js').Profile} Profile */
/** @typedef {import('./types.js').Lesson} Lesson */

/** @param {string} value @returns {string} HTMLテキストと属性をエスケープする。 */
function escapeHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

/** @param {string} title @param {string} body @param {string} prefix @returns {string} */
function document(title, body, prefix) {
  return `<!doctype html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="Content-Security-Policy" content="default-src 'self'; style-src 'self'; script-src 'self'; frame-src 'self'; img-src 'self' data:; font-src 'self'; object-src 'none'; base-uri 'none'">
  <title>${escapeHtml(title)}</title>
  <link rel="stylesheet" href="${prefix}assets/invalid.css">
</head>
<body>
  <a class="skip-link" href="#main-content">本文へ移動</a>
${body}
</body>
</html>
`;
}

/** @param {Profile} profile @returns {string} カリキュラム順の入口を生成する。 */
export function renderCourse(profile) {
  const items = profile.curriculum
    .map(
      (unit, index) =>
        `<li><a href="${unit.id}/"><span class="lesson-number">${String(index + 1).padStart(2, "0")}</span><strong>${escapeHtml(unit.title)}</strong><span>${escapeHtml(unit.goal)}</span></a></li>`,
    )
    .join("\n");
  return document(
    profile.title,
    `<main id="main-content" class="course-page">
    <p class="eyebrow">LEARNING PATH · ${escapeHtml(profile.technology)} ${escapeHtml(profile.version)}</p>
    <h1>${escapeHtml(profile.title)}</h1>
    <p class="course-goal">${escapeHtml(profile.goal)}</p>
    <p>対象読者：${escapeHtml(profile.audience)}</p>
    <h2>前提を積み上げて学ぶ</h2>
    <ol class="curriculum">${items}</ol>
    <p>各ページはスライドで全体像をつかみ、下の説明と例で動作を確かめる構成です。左右の注目説明はボタンで表示を切り替えられます。</p>
    <section><h2>使用する公式資料</h2>${sources(
      profile,
      profile.sources.map((source) => source.id),
    )}</section>
  </main>`,
    "",
  );
}

/** @param {Profile} profile @param {string[]} refs @returns {string} */
function sources(profile, refs) {
  return `<ul class="source-list">${profile.sources
    .filter((source) => refs.includes(source.id))
    .map(
      (source) =>
        `<li><a href="${escapeHtml(source.url)}">${escapeHtml(source.title)}</a> — ${escapeHtml(source.version)}、確認日 ${escapeHtml(source.checkedAt)}</li>`,
    )
    .join("")}</ul>`;
}

/** @param {Profile} profile @param {Lesson} lesson @returns {string} 学習本文と独立スライドのホストを生成する。 */
export function renderLesson(profile, lesson) {
  const index = profile.curriculum.findIndex((unit) => unit.id === lesson.id);
  const previous = profile.curriculum[index - 1];
  const next = profile.curriculum[index + 1];
  const prerequisites = lesson.prerequisites
    .map((value) => `<li>${escapeHtml(value)}</li>`)
    .join("");
  const explanation = lesson.explanation
    .map(
      (section) =>
        `<section><h3>${escapeHtml(section.title)}</h3><p>${escapeHtml(section.body).replaceAll("\n", "<br>")}</p>${section.code ? `<pre><code>${escapeHtml(section.code)}</code></pre>` : ""}${section.output ? `<p class="output-label">期待する実行結果</p><pre class="expected-output"><code>${escapeHtml(section.output)}</code></pre>` : ""}</section>`,
    )
    .join("\n");
  const data = JSON.stringify({
    slides: lesson.slides.map((slide) => ({ ...slide, file: `deck/slides/${slide.file}` })),
  }).replaceAll("<", "\\u003c");
  return document(
    `${lesson.title} | ${profile.title}`,
    `<header class="lesson-header">
    <a href="../">← ${escapeHtml(profile.title)}</a>
    <p class="eyebrow">LESSON ${String(index + 1).padStart(2, "0")} / ${String(profile.curriculum.length).padStart(2, "0")} · ${escapeHtml(profile.technology)} ${escapeHtml(profile.version)}</p>
    <h1>${escapeHtml(lesson.title)}</h1>
    <p class="lesson-goal">${escapeHtml(lesson.goal)}</p>
  </header>
  <main id="main-content">
    <section class="slide-section" aria-label="スライドと注目説明">
      <div class="slide-toolbar">
        <button type="button" id="slide-previous" aria-label="前のスライド">← 前へ</button>
        <p id="slide-status" aria-live="polite"></p>
        <button type="button" id="slide-next" aria-label="次のスライド">次へ →</button>
        <button type="button" id="annotation-toggle" aria-pressed="true">注目説明</button>
      </div>
      <div id="lesson-workspace">
        <aside id="notes-left" aria-label="左の注目説明"></aside>
        <div id="slide-stage"><iframe id="slide-frame" width="1600" height="900" title="${escapeHtml(lesson.title)}のスライド" sandbox="allow-same-origin"></iframe></div>
        <aside id="notes-right" aria-label="右の注目説明"></aside>
        <svg id="annotation-overlay" aria-hidden="true"></svg>
      </div>
      <p id="slide-error" role="status"></p>
    </section>
    <article class="lesson-body">
      <section><h2>この学習で使う前提</h2><ul>${prerequisites}</ul></section>
      <section><h2>スライドから具体的な動作へ</h2>${explanation}</section>
      <section class="exercise"><h2>自分で確かめる</h2><p>${escapeHtml(lesson.exercise.prompt)}</p><details><summary>解説を読む</summary><p>${escapeHtml(lesson.exercise.answer)}</p></details></section>
      <section><h2>この学習の出典</h2>${sources(profile, lesson.sources)}</section>
    </article>
    <nav class="lesson-navigation" aria-label="学習項目の移動">${previous ? `<a href="../${previous.id}/">← ${escapeHtml(previous.title)}</a>` : "<span></span>"}${next ? `<a href="../${next.id}/">${escapeHtml(next.title)} →</a>` : `<a href="../">学習一覧へ戻る</a>`}</nav>
  </main>
  <script id="learning-data" type="application/json">${data}</script>
  <script type="module" src="../assets/learning.mjs"></script>`,
    "../",
  );
}

/** @param {Profile} profile @returns {string} 対象別スキルを入力から再現可能に生成する。 */
export function renderSkill(profile) {
  return `---
name: learn-${profile.id}
description: ${JSON.stringify(`${profile.technology} ${profile.version}を、${profile.goal}ために体系的に学ぶHTML教材を作成・更新する。対象の学習、教材追加、例の説明、資料更新の依頼で使う。`)}
---

# ${profile.technology}を体系的に学ぶ

到達目標：${profile.goal}
対象読者：${profile.audience}

このファイルはprofileからの生成物である。対象版と資料の正本は [profile.json](references/profile.json)、資料URLは [sources.md](references/sources.md)、取得と更新は [workflow.md](references/workflow.md) に置く。

1. workflow.mdを読み、登録された公式資料を実際に取得する。取得できた本文と対象版だけを根拠にし、未取得は確認済みと書かない。
2. 入力のprofileと同じidを持つコースディレクトリを利用先で特定する。候補が複数あれば依頼の対象を確定する。
3. profile.curriculumの前提と順序に従い、1学習項目1到達目標で作る。既に分かっている目標や前提を聞き直さない。
4. 兄弟のlearning-setupスキルの [教材作成手順](../learning-setup/references/authoring.md) に従い、同梱html-deckを使ってdeckを作る。スライドを短く保ち、前提・流れ・実行例・練習をlesson.jsonへ書く。
5. 注目対象はdata-learning-targetで特定し、左右の説明と対応させる。対象や例を変えたら本文・注目点・出力・出典も照合する。
6. learning-setup/scripts/learning.mjsのcheck/build、html-deckの実測検査、学習ページの表示を確認する。失敗、未実施、人間の確認待ちを分けて報告する。

スライドの制作と実測は兄弟のlearning-setup/vendor/html-deck/SKILL.mdを使う。外側の学習ページはそのスライドHTMLを同一originのiframeに埋め込む。
`;
}

/** @param {Profile} profile @returns {string} */
export function renderSources(profile) {
  return `# ${profile.technology}の公式資料\n\n対象版：${profile.version}。以下の確認日はprofileの入力値であり、この生成コマンドがネットワーク取得したという意味ではない。制作時にはworkflowの取得手順を実行する。\n\n${profile.sources.map((source) => `- **${source.id}** [${source.title}](${source.url}) — ${source.version}、確認日 ${source.checkedAt}`).join("\n")}\n`;
}

/** @param {Profile} profile @returns {string} */
export function renderWorkflow(profile) {
  return `# ${profile.technology}の情報取得と更新\n\n1. sources.mdのURLをWeb取得ツールまたはブラウザで開く。公式host（${profile.officialHosts.join(", ")}）と対象版（${profile.version}）を照合する。\n2. HTMLの外枠だけ、404、アクセス拒否を本文取得成功と扱わない。取得した節と教材に使う主張を対応付ける。取得不能なら別の公式URLを調べ、未取得を記録する。\n3. 言語仕様・API・Getting started・release notesを突き合わせ、前提から各到達目標までの順序をprofile.curriculumで確認する。\n4. codeを実行し、観測した結果と期待だけの結果を区別する。実行できない環境では未実施と明記する。\n5. 更新では同じURLとrelease notesを再取得し、資料の移転・対象版差分・例の変更を確認する。確認できた資料だけcheckedAtを更新する。\n6. profile、lesson.json、deck、注目対象、期待出力を照合してcheck/build/実測をやり直す。最後にsync-skillでこの参照一覧を再生成する。\n\nこれは資料を取得・確認するための手順であり、生成だけで最新情報の確認が済むことを意味しない。\n`;
}

import { createHash } from "node:crypto";
import { lstat, mkdir, readFile, readdir, realpath, unlink, writeFile } from "node:fs/promises";
import { dirname, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { parseProfile, readCourse } from "./model.mjs";
import {
  renderCourse,
  renderLesson,
  renderSkill,
  renderSources,
  renderWorkflow,
} from "./render.mjs";

/** @typedef {import('./types.js').Profile} Profile */
/** @typedef {{schemaVersion: 1, id: string, files: Record<string, string>}} Ledger */

const SELF = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const MARKER = ".learning-generated.json";
const OMIT = new Set([".venv", ".loop", "__pycache__", "node_modules", ".DS_Store"]);

/** @param {unknown} error @returns {boolean} */
function isMissing(error) {
  return typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT";
}

/** @param {string} path @returns {Promise<boolean>} */
async function exists(path) {
  try {
    await lstat(path);
    return true;
  } catch (error) {
    if (isMissing(error)) {
      return false;
    }
    throw error;
  }
}

/** @param {string} path @returns {Promise<string>} 未作成の出力先も既存の親の実パスから正規化する。 */
async function location(path) {
  const absolute = resolve(path);
  if (await exists(absolute)) {
    return realpath(absolute);
  }
  return resolve(await location(dirname(absolute)), relative(dirname(absolute), absolute));
}

/** @param {Uint8Array} content @returns {string} */
function hash(content) {
  return createHash("sha256").update(content).digest("hex");
}

/** @param {string} root @param {string} leaf @returns {Promise<string>} 出力ルート内の通常ファイルパスだけを返す。 */
async function safePath(root, leaf) {
  const base = resolve(root);
  const path = resolve(base, leaf);
  if (!leaf || path === base || !path.startsWith(base + sep)) {
    throw new Error(`OPS-02 ${leaf}: 出力先の外は変更できません`);
  }
  let current = path;
  while (current === base || current.startsWith(base + sep)) {
    if (await exists(current)) {
      const info = await lstat(current);
      if (info.isSymbolicLink()) {
        throw new Error(`OPS-02 ${current}: 出力先にsymlinkは使えません`);
      }
    }
    if (current === base) {
      break;
    }
    current = dirname(current);
  }
  return path;
}

/** @param {string} root @returns {Promise<Map<string, Buffer>>} 自己完結する配布物をバイナリのまま読む。 */
async function tree(root) {
  /** @type {Map<string, Buffer>} */
  const files = new Map();
  /** @param {string} directory @returns {Promise<void>} */
  async function visit(directory) {
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      if (OMIT.has(entry.name)) {
        continue;
      }
      const path = resolve(directory, entry.name);
      if (entry.isSymbolicLink()) {
        throw new Error(`OPS-02 ${path}: 配布物にsymlinkは使えません`);
      }
      if (entry.isDirectory()) {
        await visit(path);
      } else if (entry.isFile()) {
        files.set(relative(root, path), await readFile(path));
      }
    }
  }
  await visit(root);
  return files;
}

/** @param {Map<string, Buffer>} files @param {string} id @returns {Buffer} */
function ledgerContent(files, id) {
  return Buffer.from(
    JSON.stringify(
      {
        schemaVersion: 1,
        id,
        files: Object.fromEntries([...files].map(([path, content]) => [path, hash(content)])),
      },
      null,
      2,
    ) + "\n",
  );
}

/** @param {Profile} profile @returns {Map<string, Buffer>} */
function skillFiles(profile) {
  return new Map([
    ["SKILL.md", Buffer.from(renderSkill(profile))],
    ["references/profile.json", Buffer.from(JSON.stringify(profile, null, 2) + "\n")],
    ["references/sources.md", Buffer.from(renderSources(profile))],
    ["references/workflow.md", Buffer.from(renderWorkflow(profile))],
  ]);
}

/** @param {Map<string, Buffer>} writes @returns {Promise<void>} 衝突を全件確認してから新規ファイルだけを書く。 */
async function createFiles(writes) {
  for (const [path, content] of writes) {
    if (await exists(path)) {
      if (!(await lstat(path)).isFile() || !(await readFile(path)).equals(content)) {
        throw new Error(`ERR-02 ${path}: 既存ファイルと衝突します`);
      }
    }
  }
  /** @type {string[]} */
  const created = [];
  try {
    for (const [path, content] of writes) {
      if (await exists(path)) {
        continue;
      }
      await mkdir(dirname(path), { recursive: true });
      await writeFile(path, content, { flag: "wx" });
      created.push(path);
    }
  } catch (error) {
    for (const path of created.reverse()) {
      await unlink(path);
    }
    throw error;
  }
}

/** @param {string} root @param {Profile} profile @param {Map<string, Buffer>} files @returns {Promise<void>} */
async function writeManaged(root, profile, files) {
  const marker = await safePath(root, MARKER);
  /** @type {Ledger | undefined} */
  let previous;
  if (await exists(marker)) {
    const value = /** @type {unknown} */ (JSON.parse(await readFile(marker, "utf8")));
    if (
      typeof value !== "object" ||
      value === null ||
      !("schemaVersion" in value) ||
      value.schemaVersion !== 1 ||
      !("id" in value) ||
      value.id !== profile.id ||
      !("files" in value) ||
      typeof value.files !== "object" ||
      value.files === null ||
      Array.isArray(value.files)
    ) {
      throw new Error("ERR-02 所有マーカーが一致しません");
    }
    previous = /** @type {Ledger} */ (value);
  } else if ((await exists(root)) && (await readdir(root)).length !== 0) {
    throw new Error("ERR-02 空でない出力先に所有マーカーがありません");
  }
  for (const [leaf, expected] of Object.entries(previous?.files ?? {})) {
    const path = await safePath(root, leaf);
    if (
      !(await exists(path)) ||
      !(await lstat(path)).isFile() ||
      hash(await readFile(path)) !== expected
    ) {
      throw new Error(`ERR-02 ${leaf}: 生成後に変更されています。別の出力先へ生成してください`);
    }
  }
  for (const [leaf] of files) {
    const path = await safePath(root, leaf);
    if ((await exists(path)) && !Object.hasOwn(previous?.files ?? {}, leaf)) {
      throw new Error(`ERR-02 ${leaf}: 利用者ファイルと衝突します`);
    }
  }
  for (const [leaf, content] of files) {
    const path = await safePath(root, leaf);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, content);
  }
  for (const leaf of Object.keys(previous?.files ?? {})) {
    if (!files.has(leaf)) {
      await unlink(await safePath(root, leaf));
    }
  }
  await mkdir(root, { recursive: true });
  await writeFile(marker, ledgerContent(files, profile.id));
}

/** @param {string} profilePath @param {string} courseDir @param {string} skillsDir @returns {Promise<void>} */
async function setup(profilePath, courseDir, skillsDir) {
  const profile = parseProfile(JSON.parse(await readFile(profilePath, "utf8")));
  /** @type {Map<string, Buffer>} */
  const writes = new Map();
  writes.set(
    await safePath(courseDir, "profile.json"),
    Buffer.from(JSON.stringify(profile, null, 2) + "\n"),
  );
  const generated = skillFiles(profile);
  generated.set(MARKER, ledgerContent(generated, profile.id));
  for (const [leaf, content] of generated) {
    writes.set(await safePath(resolve(skillsDir, `learn-${profile.id}`), leaf), content);
  }
  const setupDir = resolve(skillsDir, "learning-setup");
  const same = (await exists(setupDir)) && (await realpath(setupDir)) === (await realpath(SELF));
  if (!same) {
    for (const [leaf, content] of await tree(SELF)) {
      writes.set(await safePath(setupDir, leaf), content);
    }
  }
  await createFiles(writes);
  console.log(
    `setup: learn-${profile.id} と公式資料・取得手順を生成しました。教材本文は未作成です。`,
  );
}

/** @param {string} courseDir @returns {Promise<Profile>} */
async function readProfile(courseDir) {
  return parseProfile(JSON.parse(await readFile(resolve(courseDir, "profile.json"), "utf8")));
}

/** @param {string} courseDir @param {string} outputDir @returns {Promise<void>} */
async function build(courseDir, outputDir) {
  const input = await location(courseDir);
  const output = await location(outputDir);
  if (input === output || input.startsWith(output + sep) || output.startsWith(input + sep)) {
    throw new Error("ERR-02 入力コースと出力先を別の場所にしてください");
  }
  const course = await readCourse(courseDir);
  /** @type {Map<string, Buffer>} */
  const files = new Map([["index.html", Buffer.from(renderCourse(course.profile))]]);
  for (const [leaf, content] of await tree(resolve(SELF, "assets/web"))) {
    files.set(`assets/${leaf}`, content);
  }
  for (const { lesson, deckDir } of course.lessons) {
    files.set(`${lesson.id}/index.html`, Buffer.from(renderLesson(course.profile, lesson)));
    for (const [leaf, content] of await tree(deckDir)) {
      files.set(`${lesson.id}/deck/${leaf}`, content);
    }
  }
  await writeManaged(outputDir, course.profile, files);
  console.log(`build: ${course.lessons.length} 学習項目 → ${resolve(outputDir)}`);
}

/** @param {string[]} args @param {number} count @returns {string[]} */
function argumentsFor(args, count) {
  if (args.length !== count || args.some((arg) => !arg || arg.startsWith("--"))) {
    throw new Error("ERR-02 引数の数が違います。helpを参照してください");
  }
  return args;
}

/** @param {string[]} args @returns {Promise<void>} */
async function dispatch(args) {
  const [command, ...values] = args;
  if (!command || command === "help" || command === "--help") {
    console.log(
      "learning setup <profile.json> <course-dir> <skills-dir>\nlearning sync-skill <course-dir> <skills-dir>\nlearning check <course-dir>\nlearning build <course-dir> <output-dir>\nlearning sources <course-dir>\nlearning format-file <json>",
    );
    return;
  }
  const counts = new Map([
    ["setup", 3],
    ["sync-skill", 2],
    ["check", 1],
    ["build", 2],
    ["sources", 1],
    ["format-file", 1],
  ]);
  const count = counts.get(command);
  if (count === undefined) {
    throw new Error(`ERR-02 不明なコマンド: ${command}`);
  }
  const checked = argumentsFor(values, count);
  const first = checked[0];
  if (first === undefined) {
    throw new Error("ERR-02 入力がありません");
  }
  if (command === "setup") {
    return setup(first, checked[1] ?? "", checked[2] ?? "");
  }
  if (command === "build") {
    return build(first, checked[1] ?? "");
  }
  if (command === "check") {
    const course = await readCourse(first);
    console.log(`check: ${course.profile.id} / ${course.lessons.length} lessons passed`);
    return;
  }
  if (command === "format-file") {
    if (!first.endsWith(".json")) {
      throw new Error("ERR-02 format-fileはJSONファイルだけに使えます");
    }
    await writeFile(
      first,
      JSON.stringify(JSON.parse(await readFile(first, "utf8")), null, 2) + "\n",
    );
    return;
  }
  const profile = await readProfile(first);
  if (command === "sources") {
    console.log(renderSources(profile));
    return;
  }
  await writeManaged(
    resolve(checked[1] ?? "", `learn-${profile.id}`),
    profile,
    skillFiles(profile),
  );
  console.log(`sync-skill: learn-${profile.id}`);
}

/** @param {string[]} args @returns {Promise<void>} CLI境界だけで例外を終了コードへ変換する。 */
export async function main(args) {
  try {
    await dispatch(args);
  } catch (error) {
    console.log(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  }
}

if (
  process.argv[1] &&
  (await realpath(process.argv[1])) === (await realpath(fileURLToPath(import.meta.url)))
) {
  await main(process.argv.slice(2));
}

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const ANNOTATION_PADDING = 7;
const SVG_NAMESPACE = "http://www.w3.org/2000/svg";

/** @type {Runtime|null} */
let activeRuntime = null;

/** @returns {Runtime} */
function getRuntime() {
  if (!activeRuntime) {
    throw new Error("教材が初期化されていません。");
  }
  return activeRuntime;
}

/** @typedef {{id:string,target:string,side:"left"|"right",title:string,body:string}} Note */
/** @typedef {{file:string,title:string,notes:Note[]}} Slide */
/** @typedef {{workspace:HTMLElement,stage:HTMLElement,frame:HTMLIFrameElement,overlay:SVGSVGElement,left:HTMLElement,right:HTMLElement,toggle:HTMLButtonElement,previous:HTMLButtonElement,next:HTMLButtonElement,status:HTMLElement,error:HTMLElement}} Elements */
/** @typedef {{elements:Elements,slides:Slide[],index:number,revision:number,isAnnotationsVisible:boolean,activeDocument:Document|null,animationFrame:number,cleanupDocument:()=>void,cards:Map<string,HTMLElement>}} Runtime */

/** @param {unknown} value @returns {value is Record<string,unknown>} */
function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** @param {unknown} value @param {string} field @returns {string} */
function readString(value, field) {
  if (typeof value !== "string" || value.trim() === "") {
    throw new Error(`教材データの ${field} が空か文字列以外です。`);
  }
  return value;
}

/** @param {unknown} value @returns {Note} */
function parseNote(value) {
  if (!isRecord(value)) {
    throw new Error("注目ポイントの形式が不正です。");
  }
  const id = readString(value.id, "note.id");
  const target = readString(value.target, "note.target");
  if (
    !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(id) ||
    !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(target)
  ) {
    throw new Error("注目ポイントのIDと対象はkebab-caseで指定します。");
  }
  if (value.side !== "left" && value.side !== "right") {
    throw new Error("注目ポイントのsideはleftまたはrightです。");
  }
  return {
    id,
    target,
    side: value.side,
    title: readString(value.title, "note.title"),
    body: readString(value.body, "note.body"),
  };
}

/** @param {unknown} value @returns {Slide} */
function parseSlide(value) {
  if (!isRecord(value) || !Array.isArray(value.notes)) {
    throw new Error("スライドの形式が不正です。");
  }
  const file = readString(value.file, "slide.file");
  if (!/^deck\/slides\/[a-z0-9][a-z0-9-]*\.html$/u.test(file)) {
    throw new Error("スライドの参照先はdeck/slides内のHTMLに限定します。");
  }
  const notes = value.notes.map(parseNote);
  if (
    new Set(
      notes.map(function (note) {
        return note.id;
      }),
    ).size !== notes.length ||
    new Set(
      notes.map(function (note) {
        return note.target;
      }),
    ).size !== notes.length
  ) {
    throw new Error("同じスライド内の注目IDと対象は重複できません。");
  }
  return { file, title: readString(value.title, "slide.title"), notes };
}

/** @returns {Slide[]} */
function readSlides() {
  const element = document.getElementById("learning-data");
  if (!(element instanceof HTMLScriptElement) || element.type !== "application/json") {
    throw new Error("教材データが見つかりません。");
  }
  /** @type {unknown} */
  const value = JSON.parse(element.textContent ?? "");
  if (!isRecord(value) || !Array.isArray(value.slides) || value.slides.length === 0) {
    throw new Error("教材には1枚以上のスライドが必要です。");
  }
  return value.slides.map(parseSlide);
}

/** @param {string} id @returns {HTMLElement} */
function requireElement(id) {
  const element = document.getElementById(id);
  if (!(element instanceof HTMLElement)) {
    throw new Error(`表示要素 #${id} が見つかりません。`);
  }
  return element;
}

/** @param {string} id @returns {HTMLButtonElement} */
function requireButton(id) {
  const element = requireElement(id);
  if (!(element instanceof HTMLButtonElement)) {
    throw new Error(`#${id} はbuttonで指定します。`);
  }
  return element;
}

/** @returns {Elements} */
function readElements() {
  const frame = requireElement("slide-frame");
  const overlay = document.querySelector("#annotation-overlay");
  if (!(frame instanceof HTMLIFrameElement) || !(overlay instanceof SVGSVGElement)) {
    throw new Error("スライドのiframeまたは注目表示のSVGが見つかりません。");
  }
  return {
    workspace: requireElement("lesson-workspace"),
    stage: requireElement("slide-stage"),
    frame,
    overlay,
    left: requireElement("notes-left"),
    right: requireElement("notes-right"),
    toggle: requireButton("annotation-toggle"),
    previous: requireButton("slide-previous"),
    next: requireButton("slide-next"),
    status: requireElement("slide-status"),
    error: requireElement("slide-error"),
  };
}

/** @param {string} message @returns {void} */
function showError(message) {
  const runtime = getRuntime();
  runtime.elements.error.textContent = message;
  runtime.elements.error.hidden = message === "";
}

/** @returns {number} */
function indexFromHash() {
  const runtime = getRuntime();
  const match = /^#slide-([1-9][0-9]*)$/u.exec(location.hash);
  const number = match ? Number(match[1]) : 1;
  if (!Number.isSafeInteger(number) || number > runtime.slides.length) {
    return 0;
  }
  return number - 1;
}

/** @param {Slide} slide @returns {void} */
function renderNotes(slide) {
  const runtime = getRuntime();
  runtime.cards.clear();
  runtime.elements.left.replaceChildren();
  runtime.elements.right.replaceChildren();
  slide.notes.forEach(function (note, index) {
    const card = document.createElement("article");
    card.className = "note-card";
    card.dataset.noteId = note.id;
    card.id = `note-${note.id}`;
    const title = document.createElement("h3");
    title.textContent = `${index + 1}. ${note.title}`;
    const body = document.createElement("p");
    body.textContent = note.body;
    card.append(title, body);
    const column = note.side === "left" ? runtime.elements.left : runtime.elements.right;
    column.append(card);
    runtime.cards.set(note.id, card);
  });
}

/** @returns {void} */
function applyVisibility() {
  const runtime = getRuntime();
  const isVisible = runtime.isAnnotationsVisible;
  runtime.elements.left.hidden = false;
  runtime.elements.right.hidden = !isVisible;
  runtime.elements.overlay.toggleAttribute("hidden", !isVisible);
  runtime.elements.workspace.dataset.annotations = isVisible ? "on" : "off";
  runtime.elements.toggle.setAttribute("aria-pressed", String(isVisible));
  runtime.elements.toggle.textContent = isVisible ? "注目ポイントを隠す" : "注目ポイントを表示";
  scheduleDraw();
}

/** @param {number} index @param {boolean} isUserNavigation @returns {void} */
function moveSlide(index, isUserNavigation) {
  const runtime = getRuntime();
  const slide = runtime.slides[index];
  if (!slide) {
    return;
  }
  const hash = `#slide-${index + 1}`;
  if (location.hash !== hash) {
    if (isUserNavigation) {
      history.pushState(null, "", hash);
    } else {
      history.replaceState(null, "", hash);
    }
  }
  if (runtime.index === index) {
    return;
  }
  runtime.revision += 1;
  runtime.cleanupDocument();
  runtime.activeDocument = null;
  runtime.index = index;
  runtime.elements.overlay.replaceChildren();
  showError("");
  renderNotes(slide);
  runtime.elements.previous.disabled = index === 0;
  runtime.elements.next.disabled = index === runtime.slides.length - 1;
  runtime.elements.status.textContent = `${index + 1} / ${runtime.slides.length} — ${slide.title}`;
  runtime.elements.frame.title = slide.title;
  const frameWindow = runtime.elements.frame.contentWindow;
  if (!frameWindow) {
    showError("スライドの表示領域を初期化できません。");
    return;
  }
  // iframe自身の履歴を増やすと、戻る操作が親のhashと分かれてしまう。
  frameWindow.location.replace(new URL(slide.file, location.href).href);
  applyVisibility();
}

/** @param {KeyboardEvent} event @returns {void} */
function onKey(event) {
  const runtime = getRuntime();
  const target = event.target;
  const isEditable =
    target instanceof HTMLElement &&
    (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/u.test(target.tagName));
  if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || isEditable) {
    return;
  }
  /** @type {Record<string,number>} */
  const destinations = {
    ArrowLeft: runtime.index - 1,
    ArrowRight: runtime.index + 1,
    Home: 0,
    End: runtime.slides.length - 1,
  };
  const destination = destinations[event.key];
  if (destination === undefined) {
    return;
  }
  event.preventDefault();
  moveSlide(destination, true);
}

/** @param {Document} frameDocument @param {number} revision @returns {boolean} */
function isCurrentDocument(frameDocument, revision) {
  const runtime = getRuntime();
  const slide = runtime.slides[runtime.index];
  return Boolean(
    slide &&
    runtime.revision === revision &&
    runtime.elements.frame.contentDocument === frameDocument &&
    frameDocument.URL === new URL(slide.file, location.href).href,
  );
}

/** @returns {Promise<void>} */
async function connectFrame() {
  const runtime = getRuntime();
  const revision = runtime.revision;
  let frameDocument = null;
  try {
    frameDocument = runtime.elements.frame.contentDocument;
  } catch {
    showError("注目表示には学習ページとスライドを同じHTTPサーバーで開く必要があります。");
    return;
  }
  if (!frameDocument) {
    showError("スライドを読み込めません。同じHTTPサーバーから開いてください。");
    return;
  }
  if (!isCurrentDocument(frameDocument, revision)) {
    return;
  }
  if (!frameDocument.querySelector(".slide")) {
    showError("スライドの本文を読み込めません。HTMLファイルを確認してください。");
    return;
  }
  runtime.activeDocument = frameDocument;
  bindFrameEvents(frameDocument, revision);
  scheduleDraw();
  await frameDocument.fonts.ready;
  if (isCurrentDocument(frameDocument, revision)) {
    scheduleDraw();
  }
}

/** @param {Document} frameDocument @param {number} revision @returns {void} */
function bindFrameEvents(frameDocument, revision) {
  const runtime = getRuntime();
  function update() {
    if (isCurrentDocument(frameDocument, revision)) {
      scheduleDraw();
    }
  }
  function key(/** @type {KeyboardEvent} */ event) {
    onKey(event);
  }
  frameDocument.addEventListener("animationend", update, true);
  frameDocument.addEventListener("transitionend", update, true);
  frameDocument.addEventListener("keydown", key);
  frameDocument.fonts.addEventListener("loadingdone", update);
  const observer = new ResizeObserver(update);
  const slide = runtime.slides[runtime.index];
  if (slide) {
    slide.notes.forEach(function (note) {
      const target = frameDocument.querySelector(`[data-learning-target="${note.target}"]`);
      if (target) {
        observer.observe(target);
      }
    });
  }
  runtime.cleanupDocument = function () {
    observer.disconnect();
    frameDocument.removeEventListener("animationend", update, true);
    frameDocument.removeEventListener("transitionend", update, true);
    frameDocument.removeEventListener("keydown", key);
    frameDocument.fonts.removeEventListener("loadingdone", update);
  };
}

/** @returns {void} */
function scheduleDraw() {
  const runtime = getRuntime();
  if (runtime.animationFrame) {
    cancelAnimationFrame(runtime.animationFrame);
  }
  const revision = runtime.revision;
  runtime.animationFrame = requestAnimationFrame(function () {
    runtime.animationFrame = 0;
    if (revision === runtime.revision) {
      drawAnnotations();
    }
  });
}

/** @returns {SVGDefsElement} */
function createArrow() {
  const definitions = document.createElementNS(SVG_NAMESPACE, "defs");
  const marker = document.createElementNS(SVG_NAMESPACE, "marker");
  marker.id = "annotation-arrow";
  marker.setAttribute("viewBox", "0 0 10 10");
  marker.setAttribute("refX", "9");
  marker.setAttribute("refY", "5");
  marker.setAttribute("markerWidth", "7");
  marker.setAttribute("markerHeight", "7");
  marker.setAttribute("orient", "auto");
  const arrow = document.createElementNS(SVG_NAMESPACE, "path");
  arrow.setAttribute("d", "M 0 0 L 10 5 L 0 10 z");
  arrow.setAttribute("fill", "context-stroke");
  marker.append(arrow);
  definitions.append(marker);
  return definitions;
}

/** @typedef {{x:number,y:number,width:number,height:number}} Rectangle */
/** @param {Document} frameDocument @returns {Rectangle[]} */
function textRectangles(frameDocument) {
  const range = frameDocument.createRange();
  // SHOW_TEXT=4。iframe内の実際の文字行だけを衝突判定に使う。
  const walker = frameDocument.createTreeWalker(frameDocument.body, 4);
  /** @type {Rectangle[]} */
  const rectangles = [];
  let node = walker.nextNode();
  while (node) {
    if (node.textContent?.trim()) {
      range.selectNodeContents(node);
      for (const rectangle of range.getClientRects()) {
        if (rectangle.width > 0 && rectangle.height > 0) {
          rectangles.push(translateRectangle(rectangle));
        }
      }
    }
    node = walker.nextNode();
  }
  return rectangles;
}

/** @param {DOMRect} target @returns {Rectangle} */
function translateRectangle(target) {
  const runtime = getRuntime();
  const frame = runtime.elements.frame.getBoundingClientRect();
  const overlay = runtime.elements.overlay.getBoundingClientRect();
  const scaleX = frame.width / CANVAS_WIDTH;
  const scaleY = frame.height / CANVAS_HEIGHT;
  return {
    x: frame.left - overlay.left + target.left * scaleX,
    y: frame.top - overlay.top + target.top * scaleY,
    width: target.width * scaleX,
    height: target.height * scaleY,
  };
}

/** @param {Rectangle} left @param {Rectangle} right @returns {boolean} */
function rectanglesOverlap(left, right) {
  return (
    left.x < right.x + right.width &&
    left.x + left.width > right.x &&
    left.y < right.y + right.height &&
    left.y + left.height > right.y
  );
}

/** @param {number} origin @param {number} minimum @param {number} maximum @returns {number[]} */
function labelCoordinates(origin, minimum, maximum) {
  const positions = [Math.max(minimum, Math.min(maximum, origin)), maximum];
  // CSSピクセルで探すため、縮小したコードの行間に番号を押し込まない。
  for (let position = minimum; position <= maximum; position += 8) {
    positions.push(position);
  }
  return [...new Set(positions)].sort(function (left, right) {
    return Math.abs(left - origin) - Math.abs(right - origin);
  });
}

/** @param {SVGTextElement} label @param {Rectangle} target @param {"left"|"right"} side @param {Rectangle[]} obstacles @returns {Rectangle|null} */
function placeLabel(label, target, side, obstacles) {
  const runtime = getRuntime();
  const frame = runtime.elements.frame.getBoundingClientRect();
  const overlay = runtime.elements.overlay.getBoundingClientRect();
  const bounds = label.getBBox();
  // 白い縁取りも含めて文字から離し、番号全体をスライド内へ収める。
  const width = bounds.width + 4;
  const height = bounds.height + 4;
  const originX =
    side === "left"
      ? target.x - ANNOTATION_PADDING - 4 - width
      : target.x + target.width + ANNOTATION_PADDING + 4;
  const columns = labelCoordinates(
    originX,
    frame.left - overlay.left + 2,
    frame.right - overlay.left - width - 2,
  );
  const rows = labelCoordinates(
    target.y + (target.height - height) / 2,
    frame.top - overlay.top + 2,
    frame.bottom - overlay.top - height - 2,
  );
  for (const y of rows) {
    for (const x of columns) {
      const candidate = { x, y, width, height };
      if (
        !obstacles.some(function (obstacle) {
          return rectanglesOverlap(candidate, obstacle);
        })
      ) {
        label.setAttribute("x", String(x - bounds.x + 2));
        label.setAttribute("y", String(y - bounds.y + 2));
        return candidate;
      }
    }
  }
  return null;
}

/** @param {DOMRect} card @param {Rectangle} target @param {DOMRect} overlay @param {"left"|"right"} side @returns {string} */
function arrowPath(card, target, overlay, side) {
  const centerY = target.y + target.height / 2;
  if (card.top - overlay.top > target.y + target.height) {
    const isLeft = side === "left";
    const startX = (isLeft ? card.left : card.right) - overlay.left;
    const startY = card.top - overlay.top + card.height / 2;
    const gutterX = isLeft ? 4 : overlay.width - 4;
    const endX = isLeft
      ? target.x - ANNOTATION_PADDING
      : target.x + target.width + ANNOTATION_PADDING;
    // 縦に並んだ他のカードへ線を通さず、左右の余白から対象へ戻す。
    return `M ${startX} ${startY} H ${gutterX} V ${centerY} H ${endX}`;
  }
  const isLeft = side === "left";
  const startX = (isLeft ? card.right : card.left) - overlay.left;
  const startY = card.top - overlay.top + card.height / 2;
  const endX = isLeft
    ? target.x - ANNOTATION_PADDING
    : target.x + target.width + ANNOTATION_PADDING;
  const middleX = (startX + endX) / 2;
  return `M ${startX} ${startY} C ${middleX} ${startY} ${middleX} ${centerY} ${endX} ${centerY}`;
}

/** @param {Note} note @param {Rectangle} target @param {number} index @returns {SVGGElement|null} */
function createAnnotation(note, target, index) {
  const runtime = getRuntime();
  const card = runtime.cards.get(note.id);
  if (!card) {
    return null;
  }
  const group = document.createElementNS(SVG_NAMESPACE, "g");
  group.dataset.noteId = note.id;
  const ellipse = document.createElementNS(SVG_NAMESPACE, "ellipse");
  ellipse.setAttribute("cx", String(target.x + target.width / 2));
  ellipse.setAttribute("cy", String(target.y + target.height / 2));
  ellipse.setAttribute("rx", String(target.width / 2 + ANNOTATION_PADDING));
  ellipse.setAttribute("ry", String(target.height / 2 + ANNOTATION_PADDING));
  const path = document.createElementNS(SVG_NAMESPACE, "path");
  path.setAttribute(
    "d",
    arrowPath(
      card.getBoundingClientRect(),
      target,
      runtime.elements.overlay.getBoundingClientRect(),
      note.side,
    ),
  );
  path.setAttribute("marker-end", "url(#annotation-arrow)");
  const label = document.createElementNS(SVG_NAMESPACE, "text");
  label.setAttribute("x", "0");
  label.setAttribute("y", "0");
  label.setAttribute("text-anchor", "middle");
  label.setAttribute("dominant-baseline", "middle");
  label.textContent = String(index + 1);
  group.append(path, ellipse, label);
  return group;
}

/** @param {Slide} slide @param {Document} frameDocument @returns {string[]} */
function drawNotes(slide, frameDocument) {
  const runtime = getRuntime();
  /** @type {string[]} */
  const errors = [];
  const obstacles = textRectangles(frameDocument);
  slide.notes.forEach(function (note, index) {
    const matches = frameDocument.querySelectorAll(`[data-learning-target="${note.target}"]`);
    const target = matches[0];
    if (matches.length !== 1 || !target) {
      errors.push(`注目対象「${note.target}」は1つ必要です（現在${matches.length}件）。`);
      return;
    }
    const rectangle = target.getBoundingClientRect();
    if (rectangle.width <= 0 || rectangle.height <= 0) {
      errors.push(`注目対象「${note.target}」を表示できません。`);
      return;
    }
    const targetRectangle = translateRectangle(rectangle);
    const annotation = createAnnotation(note, targetRectangle, index);
    if (annotation) {
      runtime.elements.overlay.append(annotation);
      const label = annotation.querySelector("text");
      if (label) {
        const placement = placeLabel(label, targetRectangle, note.side, obstacles);
        if (placement) {
          obstacles.push(placement);
        } else {
          annotation.remove();
          errors.push(`注目番号「${index + 1}」を置く余白がありません。文字量を減らしてください。`);
        }
      }
    }
  });
  return errors;
}

/** @returns {void} */
function drawAnnotations() {
  const runtime = getRuntime();
  const elements = runtime.elements;
  const scale = elements.stage.getBoundingClientRect().width / CANVAS_WIDTH;
  elements.frame.style.transform = `scale(${scale})`;
  if (!runtime.isAnnotationsVisible) {
    return;
  }
  const frameDocument = runtime.activeDocument;
  const slide = runtime.slides[runtime.index];
  if (!frameDocument || !slide || !isCurrentDocument(frameDocument, runtime.revision)) {
    return;
  }
  const rectangle = elements.overlay.getBoundingClientRect();
  elements.overlay.setAttribute("viewBox", `0 0 ${rectangle.width} ${rectangle.height}`);
  elements.overlay.replaceChildren(createArrow());
  showError(drawNotes(slide, frameDocument).join(" "));
}

/** @returns {void} */
function bindPageEvents() {
  const runtime = getRuntime();
  const elements = runtime.elements;
  elements.frame.addEventListener("load", function () {
    void connectFrame();
  });
  elements.previous.addEventListener("click", function () {
    moveSlide(runtime.index - 1, true);
  });
  elements.next.addEventListener("click", function () {
    moveSlide(runtime.index + 1, true);
  });
  elements.toggle.addEventListener("click", function () {
    runtime.isAnnotationsVisible = !runtime.isAnnotationsVisible;
    applyVisibility();
  });
  window.addEventListener("hashchange", function () {
    moveSlide(indexFromHash(), false);
  });
  window.addEventListener("resize", function () {
    scheduleDraw();
  });
  document.addEventListener("keydown", function (event) {
    onKey(event);
  });
  const observer = new ResizeObserver(function () {
    scheduleDraw();
  });
  observer.observe(elements.workspace);
  observer.observe(elements.stage);
  observer.observe(elements.left);
  observer.observe(elements.right);
}

/** @returns {void} */
function initialize() {
  if (!document.getElementById("lesson-workspace")) {
    return;
  }
  const elements = readElements();
  /** @type {Runtime} */
  const runtime = {
    elements,
    slides: readSlides(),
    index: -1,
    revision: 0,
    isAnnotationsVisible: true,
    activeDocument: null,
    animationFrame: 0,
    cleanupDocument: function () {},
    cards: new Map(),
  };
  activeRuntime = runtime;
  elements.frame.width = String(CANVAS_WIDTH);
  elements.frame.height = String(CANVAS_HEIGHT);
  elements.frame.setAttribute("sandbox", "allow-same-origin");
  elements.overlay.setAttribute("aria-hidden", "true");
  elements.overlay.setAttribute("focusable", "false");
  elements.error.setAttribute("role", "alert");
  elements.status.setAttribute("aria-live", "polite");
  bindPageEvents();
  moveSlide(indexFromHash(), false);
}

try {
  initialize();
} catch (error) {
  const element = document.getElementById("slide-error");
  if (element instanceof HTMLElement) {
    element.hidden = false;
    element.textContent = error instanceof Error ? error.message : "教材を表示できません。";
  } else {
    throw error;
  }
}

export {};

const CANVAS_WIDTH = 1600;
const CANVAS_HEIGHT = 900;
const ANNOTATION_PADDING = 7;
const SVG_NAMESPACE = "http://www.w3.org/2000/svg";

/** @type {Runtime|null} */
let activeRuntime = null;

/** @returns {Runtime} */
function getRuntime() {
  if (!activeRuntime) {
    throw new Error("教材が初期化されていません。");
  }
  return activeRuntime;
}

/** @typedef {{id:string,target:string,side:"left"|"right",title:string,body:string}} Note */
/** @typedef {{file:string,title:string,notes:Note[]}} Slide */
/** @typedef {{workspace:HTMLElement,stage:HTMLElement,frame:HTMLIFrameElement,overlay:SVGSVGElement,left:HTMLElement,right:HTMLElement,toggle:HTMLButtonElement,previous:HTMLButtonElement,next:HTMLButtonElement,status:HTMLElement,error:HTMLElement}} Elements */
/** @typedef {{elements:Elements,slides:Slide[],index:number,revision:number,isAnnotationsVisible:boolean,activeDocument:Document|null,animationFrame:number,cleanupDocument:()=>void,cards:Map<string,HTMLElement>}} Runtime */

/** @param {unknown} value @returns {value is Record<string,unknown>} */
function isRecord(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** @param {unknown} value @param {string} field @returns {string} */
function readString(value, field) {
  if (typeof value !== "string" || value.trim() === "") {
    throw new Error(`教材データの ${field} が空か文字列以外です。`);
  }
  return value;
}

/** @param {unknown} value @returns {Note} */
function parseNote(value) {
  if (!isRecord(value)) {
    throw new Error("注目ポイントの形式が不正です。");
  }
  const id = readString(value.id, "note.id");
  const target = readString(value.target, "note.target");
  if (
    !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(id) ||
    !/^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/u.test(target)
  ) {
    throw new Error("注目ポイントのIDと対象はkebab-caseで指定します。");
  }
  if (value.side !== "left" && value.side !== "right") {
    throw new Error("注目ポイントのsideはleftまたはrightです。");
  }
  return {
    id,
    target,
    side: value.side,
    title: readString(value.title, "note.title"),
    body: readString(value.body, "note.body"),
  };
}

/** @param {unknown} value @returns {Slide} */
function parseSlide(value) {
  if (!isRecord(value) || !Array.isArray(value.notes)) {
    throw new Error("スライドの形式が不正です。");
  }
  const file = readString(value.file, "slide.file");
  if (!/^deck\/slides\/[a-z0-9][a-z0-9-]*\.html$/u.test(file)) {
    throw new Error("スライドの参照先はdeck/slides内のHTMLに限定します。");
  }
  const notes = value.notes.map(parseNote);
  if (
    new Set(
      notes.map(function (note) {
        return note.id;
      }),
    ).size !== notes.length ||
    new Set(
      notes.map(function (note) {
        return note.target;
      }),
    ).size !== notes.length
  ) {
    throw new Error("同じスライド内の注目IDと対象は重複できません。");
  }
  return { file, title: readString(value.title, "slide.title"), notes };
}

/** @returns {Slide[]} */
function readSlides() {
  const element = document.getElementById("learning-data");
  if (!(element instanceof HTMLScriptElement) || element.type !== "application/json") {
    throw new Error("教材データが見つかりません。");
  }
  /** @type {unknown} */
  const value = JSON.parse(element.textContent ?? "");
  if (!isRecord(value) || !Array.isArray(value.slides) || value.slides.length === 0) {
    throw new Error("教材には1枚以上のスライドが必要です。");
  }
  return value.slides.map(parseSlide);
}

/** @param {string} id @returns {HTMLElement} */
function requireElement(id) {
  const element = document.getElementById(id);
  if (!(element instanceof HTMLElement)) {
    throw new Error(`表示要素 #${id} が見つかりません。`);
  }
  return element;
}

/** @param {string} id @returns {HTMLButtonElement} */
function requireButton(id) {
  const element = requireElement(id);
  if (!(element instanceof HTMLButtonElement)) {
    throw new Error(`#${id} はbuttonで指定します。`);
  }
  return element;
}

/** @returns {Elements} */
function readElements() {
  const frame = requireElement("slide-frame");
  const overlay = document.querySelector("#annotation-overlay");
  if (!(frame instanceof HTMLIFrameElement) || !(overlay instanceof SVGSVGElement)) {
    throw new Error("スライドのiframeまたは注目表示のSVGが見つかりません。");
  }
  return {
    workspace: requireElement("lesson-workspace"),
    stage: requireElement("slide-stage"),
    frame,
    overlay,
    left: requireElement("notes-left"),
    right: requireElement("notes-right"),
    toggle: requireButton("annotation-toggle"),
    previous: requireButton("slide-previous"),
    next: requireButton("slide-next"),
    status: requireElement("slide-status"),
    error: requireElement("slide-error"),
  };
}

/** @param {string} message @returns {void} */
function showError(message) {
  const runtime = getRuntime();
  runtime.elements.error.textContent = message;
  runtime.elements.error.hidden = message === "";
}

/** @returns {number} */
function indexFromHash() {
  const runtime = getRuntime();
  const match = /^#slide-([1-9][0-9]*)$/u.exec(location.hash);
  const number = match ? Number(match[1]) : 1;
  if (!Number.isSafeInteger(number) || number > runtime.slides.length) {
    return 0;
  }
  return number - 1;
}

/** @param {Slide} slide @returns {void} */
function renderNotes(slide) {
  const runtime = getRuntime();
  runtime.cards.clear();
  runtime.elements.left.replaceChildren();
  runtime.elements.right.replaceChildren();
  slide.notes.forEach(function (note, index) {
    const card = document.createElement("article");
    card.className = "note-card";
    card.dataset.noteId = note.id;
    card.id = `note-${note.id}`;
    const title = document.createElement("h3");
    title.textContent = `${index + 1}. ${note.title}`;
    const body = document.createElement("p");
    body.textContent = note.body;
    card.append(title, body);
    const column = note.side === "left" ? runtime.elements.left : runtime.elements.right;
    column.append(card);
    runtime.cards.set(note.id, card);
  });
}

/** @returns {void} */
function applyVisibility() {
  const runtime = getRuntime();
  const isVisible = runtime.isAnnotationsVisible;
  runtime.elements.left.hidden = !isVisible;
  runtime.elements.right.hidden = !isVisible;
  runtime.elements.overlay.toggleAttribute("hidden", !isVisible);
  runtime.elements.workspace.dataset.annotations = isVisible ? "on" : "off";
  runtime.elements.toggle.setAttribute("aria-pressed", String(isVisible));
  runtime.elements.toggle.textContent = isVisible ? "注目ポイントを隠す" : "注目ポイントを表示";
  scheduleDraw();
}

/** @param {number} index @param {boolean} isUserNavigation @returns {void} */
function moveSlide(index, isUserNavigation) {
  const runtime = getRuntime();
  const slide = runtime.slides[index];
  if (!slide) {
    return;
  }
  const hash = `#slide-${index + 1}`;
  if (location.hash !== hash) {
    if (isUserNavigation) {
      history.pushState(null, "", hash);
    } else {
      history.replaceState(null, "", hash);
    }
  }
  if (runtime.index === index) {
    return;
  }
  runtime.revision += 1;
  runtime.cleanupDocument();
  runtime.activeDocument = null;
  runtime.index = index;
  runtime.elements.overlay.replaceChildren();
  showError("");
  renderNotes(slide);
  runtime.elements.previous.disabled = index === 0;
  runtime.elements.next.disabled = index === runtime.slides.length - 1;
  runtime.elements.status.textContent = `${index + 1} / ${runtime.slides.length} — ${slide.title}`;
  runtime.elements.frame.title = slide.title;
  const frameWindow = runtime.elements.frame.contentWindow;
  if (!frameWindow) {
    showError("スライドの表示領域を初期化できません。");
    return;
  }
  // iframe自身の履歴を増やすと、戻る操作が親のhashと分かれてしまう。
  frameWindow.location.replace(new URL(slide.file, location.href).href);
  applyVisibility();
}

/** @param {KeyboardEvent} event @returns {void} */
function onKey(event) {
  const runtime = getRuntime();
  const target = event.target;
  const isEditable =
    target instanceof HTMLElement &&
    (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/u.test(target.tagName));
  if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || isEditable) {
    return;
  }
  /** @type {Record<string,number>} */
  const destinations = {
    ArrowLeft: runtime.index - 1,
    ArrowRight: runtime.index + 1,
    Home: 0,
    End: runtime.slides.length - 1,
  };
  const destination = destinations[event.key];
  if (destination === undefined) {
    return;
  }
  event.preventDefault();
  moveSlide(destination, true);
}

/** @param {Document} frameDocument @param {number} revision @returns {boolean} */
function isCurrentDocument(frameDocument, revision) {
  const runtime = getRuntime();
  const slide = runtime.slides[runtime.index];
  return Boolean(
    slide &&
    runtime.revision === revision &&
    runtime.elements.frame.contentDocument === frameDocument &&
    frameDocument.URL === new URL(slide.file, location.href).href,
  );
}

/** @returns {Promise<void>} */
async function connectFrame() {
  const runtime = getRuntime();
  const revision = runtime.revision;
  let frameDocument = null;
  try {
    frameDocument = runtime.elements.frame.contentDocument;
  } catch {
    showError("注目表示には学習ページとスライドを同じHTTPサーバーで開く必要があります。");
    return;
  }
  if (!frameDocument) {
    showError("スライドを読み込めません。同じHTTPサーバーから開いてください。");
    return;
  }
  if (!isCurrentDocument(frameDocument, revision)) {
    return;
  }
  if (!frameDocument.querySelector(".slide")) {
    showError("スライドの本文を読み込めません。HTMLファイルを確認してください。");
    return;
  }
  runtime.activeDocument = frameDocument;
  bindFrameEvents(frameDocument, revision);
  scheduleDraw();
  await frameDocument.fonts.ready;
  if (isCurrentDocument(frameDocument, revision)) {
    scheduleDraw();
  }
}

/** @param {Document} frameDocument @param {number} revision @returns {void} */
function bindFrameEvents(frameDocument, revision) {
  const runtime = getRuntime();
  function update() {
    if (isCurrentDocument(frameDocument, revision)) {
      scheduleDraw();
    }
  }
  function key(/** @type {KeyboardEvent} */ event) {
    onKey(event);
  }
  frameDocument.addEventListener("animationend", update, true);
  frameDocument.addEventListener("transitionend", update, true);
  frameDocument.addEventListener("keydown", key);
  frameDocument.fonts.addEventListener("loadingdone", update);
  const observer = new ResizeObserver(update);
  const slide = runtime.slides[runtime.index];
  if (slide) {
    slide.notes.forEach(function (note) {
      const target = frameDocument.querySelector(`[data-learning-target="${note.target}"]`);
      if (target) {
        observer.observe(target);
      }
    });
  }
  runtime.cleanupDocument = function () {
    observer.disconnect();
    frameDocument.removeEventListener("animationend", update, true);
    frameDocument.removeEventListener("transitionend", update, true);
    frameDocument.removeEventListener("keydown", key);
    frameDocument.fonts.removeEventListener("loadingdone", update);
  };
}

/** @returns {void} */
function scheduleDraw() {
  const runtime = getRuntime();
  if (runtime.animationFrame) {
    cancelAnimationFrame(runtime.animationFrame);
  }
  const revision = runtime.revision;
  runtime.animationFrame = requestAnimationFrame(function () {
    runtime.animationFrame = 0;
    if (revision === runtime.revision) {
      drawAnnotations();
    }
  });
}

/** @returns {SVGDefsElement} */
function createArrow() {
  const definitions = document.createElementNS(SVG_NAMESPACE, "defs");
  const marker = document.createElementNS(SVG_NAMESPACE, "marker");
  marker.id = "annotation-arrow";
  marker.setAttribute("viewBox", "0 0 10 10");
  marker.setAttribute("refX", "9");
  marker.setAttribute("refY", "5");
  marker.setAttribute("markerWidth", "7");
  marker.setAttribute("markerHeight", "7");
  marker.setAttribute("orient", "auto");
  const arrow = document.createElementNS(SVG_NAMESPACE, "path");
  arrow.setAttribute("d", "M 0 0 L 10 5 L 0 10 z");
  arrow.setAttribute("fill", "context-stroke");
  marker.append(arrow);
  definitions.append(marker);
  return definitions;
}

/** @typedef {{x:number,y:number,width:number,height:number}} Rectangle */
/** @param {Document} frameDocument @returns {Rectangle[]} */
function textRectangles(frameDocument) {
  const range = frameDocument.createRange();
  // SHOW_TEXT=4。iframe内の実際の文字行だけを衝突判定に使う。
  const walker = frameDocument.createTreeWalker(frameDocument.body, 4);
  /** @type {Rectangle[]} */
  const rectangles = [];
  let node = walker.nextNode();
  while (node) {
    if (node.textContent?.trim()) {
      range.selectNodeContents(node);
      for (const rectangle of range.getClientRects()) {
        if (rectangle.width > 0 && rectangle.height > 0) {
          rectangles.push(translateRectangle(rectangle));
        }
      }
    }
    node = walker.nextNode();
  }
  return rectangles;
}

/** @param {DOMRect} target @returns {Rectangle} */
function translateRectangle(target) {
  const runtime = getRuntime();
  const frame = runtime.elements.frame.getBoundingClientRect();
  const overlay = runtime.elements.overlay.getBoundingClientRect();
  const scaleX = frame.width / (CANVAS_WIDTH + 100);
  const scaleY = frame.height / CANVAS_HEIGHT;
  return {
    x: frame.left - overlay.left + target.left * scaleX,
    y: frame.top - overlay.top + target.top * scaleY,
    width: target.width * scaleX,
    height: target.height * scaleY,
  };
}

/** @param {Rectangle} left @param {Rectangle} right @returns {boolean} */
function rectanglesOverlap(left, right) {
  return (
    left.x < right.x + right.width &&
    left.x + left.width > right.x &&
    left.y < right.y + right.height &&
    left.y + left.height > right.y
  );
}

/** @param {number} origin @param {number} minimum @param {number} maximum @returns {number[]} */
function labelCoordinates(origin, minimum, maximum) {
  const positions = [Math.max(minimum, Math.min(maximum, origin)), maximum];
  // CSSピクセルで探すため、縮小したコードの行間に番号を押し込まない。
  for (let position = minimum; position <= maximum; position += 8) {
    positions.push(position);
  }
  return [...new Set(positions)].sort(function (left, right) {
    return Math.abs(left - origin) - Math.abs(right - origin);
  });
}

/** @param {SVGTextElement} label @param {Rectangle} target @param {"left"|"right"} side @param {Rectangle[]} obstacles @returns {Rectangle|null} */
function placeLabel(label, target, side, obstacles) {
  const runtime = getRuntime();
  const frame = runtime.elements.frame.getBoundingClientRect();
  const overlay = runtime.elements.overlay.getBoundingClientRect();
  const bounds = label.getBBox();
  // 白い縁取りも含めて文字から離し、番号全体をスライド内へ収める。
  const width = bounds.width + 4;
  const height = bounds.height + 4;
  const originX =
    side === "left"
      ? target.x - ANNOTATION_PADDING - 4 - width
      : target.x + target.width + ANNOTATION_PADDING + 4;
  const columns = labelCoordinates(
    originX,
    frame.left - overlay.left + 2,
    frame.right - overlay.left - width - 2,
  );
  const rows = labelCoordinates(
    target.y + (target.height - height) / 2,
    frame.top - overlay.top + 2,
    frame.bottom - overlay.top - height - 2,
  );
  for (const y of rows) {
    for (const x of columns) {
      const candidate = { x, y, width, height };
      if (
        !obstacles.some(function (obstacle) {
          return rectanglesOverlap(candidate, obstacle);
        })
      ) {
        label.setAttribute("x", String(x - bounds.x + 2));
        label.setAttribute("y", String(y - bounds.y + 2));
        return candidate;
      }
    }
  }
  return null;
}

/** @param {DOMRect} card @param {Rectangle} target @param {DOMRect} overlay @param {"left"|"right"} side @returns {string} */
function arrowPath(card, target, overlay, side) {
  const centerY = target.y + target.height / 2;
  if (card.top - overlay.top > target.y + target.height) {
    const isLeft = side === "left";
    const startX = (isLeft ? card.left : card.right) - overlay.left;
    const startY = card.top - overlay.top + card.height / 2;
    const gutterX = isLeft ? 4 : overlay.width - 4;
    const endX = isLeft
      ? target.x - ANNOTATION_PADDING
      : target.x + target.width + ANNOTATION_PADDING;
    // 縦に並んだ他のカードへ線を通さず、左右の余白から対象へ戻す。
    return `M ${startX} ${startY} H ${gutterX} V ${centerY} H ${endX}`;
  }
  const isLeft = side === "left";
  const startX = (isLeft ? card.right : card.left) - overlay.left;
  const startY = card.top - overlay.top + card.height / 2;
  const endX = isLeft
    ? target.x - ANNOTATION_PADDING
    : target.x + target.width + ANNOTATION_PADDING;
  const middleX = (startX + endX) / 2;
  return `M ${startX} ${startY} C ${middleX} ${startY} ${middleX} ${centerY} ${endX} ${centerY}`;
}

/** @param {Note} note @param {Rectangle} target @param {number} index @returns {SVGGElement|null} */
function createAnnotation(note, target, index) {
  const runtime = getRuntime();
  const card = runtime.cards.get(note.id);
  if (!card) {
    return null;
  }
  const group = document.createElementNS(SVG_NAMESPACE, "g");
  group.dataset.noteId = note.id;
  const ellipse = document.createElementNS(SVG_NAMESPACE, "ellipse");
  ellipse.setAttribute("cx", String(target.x + target.width / 2));
  ellipse.setAttribute("cy", String(target.y + target.height / 2));
  ellipse.setAttribute("rx", String(target.width / 2 + ANNOTATION_PADDING));
  ellipse.setAttribute("ry", String(target.height / 2 + ANNOTATION_PADDING));
  const path = document.createElementNS(SVG_NAMESPACE, "path");
  path.setAttribute(
    "d",
    arrowPath(
      card.getBoundingClientRect(),
      target,
      runtime.elements.overlay.getBoundingClientRect(),
      note.side,
    ),
  );
  path.setAttribute("marker-end", "url(#annotation-arrow)");
  const label = document.createElementNS(SVG_NAMESPACE, "text");
  label.setAttribute("x", "0");
  label.setAttribute("y", "0");
  label.setAttribute("text-anchor", "middle");
  label.setAttribute("dominant-baseline", "middle");
  label.textContent = String(index + 1);
  group.append(path, ellipse, label);
  return group;
}

/** @param {Slide} slide @param {Document} frameDocument @returns {string[]} */
function drawNotes(slide, frameDocument) {
  const runtime = getRuntime();
  /** @type {string[]} */
  const errors = [];
  const obstacles = textRectangles(frameDocument);
  slide.notes.forEach(function (note, index) {
    const matches = frameDocument.querySelectorAll(`[data-learning-target="${note.target}"]`);
    const target = matches[0];
    if (matches.length !== 1 || !target) {
      errors.push(`注目対象「${note.target}」は1つ必要です（現在${matches.length}件）。`);
      return;
    }
    const rectangle = target.getBoundingClientRect();
    if (rectangle.width <= 0 || rectangle.height <= 0) {
      errors.push(`注目対象「${note.target}」を表示できません。`);
      return;
    }
    const targetRectangle = translateRectangle(rectangle);
    const annotation = createAnnotation(note, targetRectangle, index);
    if (annotation) {
      runtime.elements.overlay.append(annotation);
      const label = annotation.querySelector("text");
      if (label) {
        const placement = placeLabel(label, targetRectangle, note.side, obstacles);
        if (placement) {
          obstacles.push(placement);
        } else {
          annotation.remove();
          errors.push(`注目番号「${index + 1}」を置く余白がありません。文字量を減らしてください。`);
        }
      }
    }
  });
  return errors;
}

/** @returns {void} */
function drawAnnotations() {
  const runtime = getRuntime();
  const elements = runtime.elements;
  const scale = elements.stage.getBoundingClientRect().width / CANVAS_WIDTH;
  elements.frame.style.transform = `scale(${scale})`;
  if (!runtime.isAnnotationsVisible) {
    return;
  }
  const frameDocument = runtime.activeDocument;
  const slide = runtime.slides[runtime.index];
  if (!frameDocument || !slide || !isCurrentDocument(frameDocument, runtime.revision)) {
    return;
  }
  const rectangle = elements.overlay.getBoundingClientRect();
  elements.overlay.setAttribute("viewBox", `0 0 ${rectangle.width} ${rectangle.height}`);
  elements.overlay.replaceChildren(createArrow());
  showError(drawNotes(slide, frameDocument).join(" "));
}

/** @returns {void} */
function bindPageEvents() {
  const runtime = getRuntime();
  const elements = runtime.elements;
  elements.frame.addEventListener("load", function () {
    void connectFrame();
  });
  elements.previous.addEventListener("click", function () {
    moveSlide(runtime.index - 1, true);
  });
  elements.next.addEventListener("click", function () {
    moveSlide(runtime.index + 1, true);
  });
  elements.toggle.addEventListener("click", function () {
    runtime.isAnnotationsVisible = !runtime.isAnnotationsVisible;
    applyVisibility();
  });
  window.addEventListener("hashchange", function () {
    moveSlide(indexFromHash(), false);
  });
  window.addEventListener("resize", function () {
    scheduleDraw();
  });
  document.addEventListener("keydown", function (event) {
    onKey(event);
  });
  const observer = new ResizeObserver(function () {
    scheduleDraw();
  });
  observer.observe(elements.workspace);
  observer.observe(elements.stage);
  observer.observe(elements.left);
  observer.observe(elements.right);
}

/** @returns {void} */
function initialize() {
  if (!document.getElementById("lesson-workspace")) {
    return;
  }
  const elements = readElements();
  /** @type {Runtime} */
  const runtime = {
    elements,
    slides: readSlides(),
    index: -1,
    revision: 0,
    isAnnotationsVisible: true,
    activeDocument: null,
    animationFrame: 0,
    cleanupDocument: function () {},
    cards: new Map(),
  };
  activeRuntime = runtime;
  elements.frame.width = String(CANVAS_WIDTH);
  elements.frame.height = String(CANVAS_HEIGHT);
  elements.frame.setAttribute("sandbox", "allow-same-origin");
  elements.overlay.setAttribute("aria-hidden", "true");
  elements.overlay.setAttribute("focusable", "false");
  elements.error.setAttribute("role", "alert");
  elements.status.setAttribute("aria-live", "polite");
  bindPageEvents();
  moveSlide(indexFromHash(), false);
}

try {
  initialize();
} catch (error) {
  const element = document.getElementById("slide-error");
  if (element instanceof HTMLElement) {
    element.hidden = false;
    element.textContent = error instanceof Error ? error.message : "教材を表示できません。";
  } else {
    throw error;
  }
}

export {};

/** @typedef {import('./types.js').Profile} Profile */
/** @typedef {import('./types.js').Lesson} Lesson */

/** @param {string} value @returns {string} HTMLテキストと属性をエスケープする。 */
function escapeHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "<")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

/** @param {string} title @param {string} body @param {string} prefix @returns {string} */
function document(title, body, prefix) {
  return `<!doctype html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta http-equiv="Content-Security-Policy" content="default-src 'self'; style-src 'self'; script-src 'self'; frame-src 'self'; img-src 'self' data:; font-src 'self'; object-src 'none'; base-uri 'none'">
  <title>${escapeHtml(title)}</title>
  <link rel="stylesheet" href="${prefix}assets/learning.css">
</head>
<body>
  <a class="skip-link" href="#main-content">本文へ移動</a>
${body}
</body>
</html>
`;
}

/** @param {Profile} profile @returns {string} カリキュラム順の入口を生成する。 */
export function renderCourse(profile) {
  const items = profile.curriculum
    .map(
      (unit, index) =>
        `<li><a href="${unit.id}/"><span class="lesson-number">${String(index + 1).padStart(2, "0")}</span><strong>${escapeHtml(unit.title)}</strong><span>${escapeHtml(unit.goal)}</span></a></li>`,
    )
    .join("\n");
  return document(
    profile.title,
    `<main id="main-content" class="course-page">
    <p class="eyebrow">LEARNING PATH · ${escapeHtml(profile.technology)} ${escapeHtml(profile.version)}</p>
    <h1>${escapeHtml(profile.title)}</h1>
    <p class="course-goal">${escapeHtml(profile.goal)}</p>
    <p>対象読者：${escapeHtml(profile.audience)}</p>
    <h2>前提を積み上げて学ぶ</h2>
    <ol class="curriculum">${items}</ol>
    <p>各ページはスライドで全体像をつかみ、下の説明と例で動作を確かめる構成です。左右の注目説明はボタンで表示を切り替えられます。</p>
    <section><h2>使用する公式資料</h2>${sources(
      profile,
      profile.sources.map((source) => source.id),
    )}</section>
  </main>`,
    "",
  );
}

/** @param {Profile} profile @param {string[]} refs @returns {string} */
function sources(profile, refs) {
  return `<ul class="source-list">${profile.sources
    .filter((source) => refs.includes(source.id))
    .map(
      (source) =>
        `<li><a href="${escapeHtml(source.url)}">${escapeHtml(source.title)}</a> — ${escapeHtml(source.version)}、確認日 ${escapeHtml(source.checkedAt)}</li>`,
    )
    .join("")}</ul>`;
}

/** @param {Profile} profile @param {Lesson} lesson @returns {string} 学習本文と独立スライドのホストを生成する。 */
export function renderLesson(profile, lesson) {
  const index = profile.curriculum.findIndex((unit) => unit.id === lesson.id);
  const previous = profile.curriculum[index - 1];
  const next = profile.curriculum[index + 1];
  const prerequisites = lesson.prerequisites
    .map((value) => `<li>${escapeHtml(value)}</li>`)
    .join("");
  const explanation = lesson.explanation
    .map(
      (section) =>
        `<section><h3>${escapeHtml(section.title)}</h3><p>${escapeHtml(section.body).replaceAll("\n", "<br>")}</p>${section.code ? `<pre><code>${escapeHtml(section.code)}</code></pre>` : ""}${section.output ? `<p class="output-label">期待する実行結果</p><pre class="expected-output"><code>${escapeHtml(section.output)}</code></pre>` : ""}</section>`,
    )
    .join("\n");
  const data = JSON.stringify({
    slides: lesson.slides.map((slide) => ({ ...slide, file: `deck/slides/${slide.file}` })),
  }).replaceAll("<", "\\u003c");
  return document(
    `${lesson.title} | ${profile.title}`,
    `<header class="lesson-header">
    <a href="../">← ${escapeHtml(profile.title)}</a>
    <p class="eyebrow">LESSON ${String(index + 1).padStart(2, "0")} / ${String(profile.curriculum.length).padStart(2, "0")} · ${escapeHtml(profile.technology)} ${escapeHtml(profile.version)}</p>
    <h1>${escapeHtml(lesson.title)}</h1>
    <p class="lesson-goal">${escapeHtml(lesson.goal)}</p>
  </header>
  <main id="main-content">
    <section class="slide-section" aria-label="スライドと注目説明">
      <div class="slide-toolbar">
        <button type="button" id="slide-previous" aria-label="前のスライド">← 前へ</button>
        <p id="slide-status" aria-live="polite"></p>
        <button type="button" id="slide-next" aria-label="次のスライド">次へ →</button>
        <button type="button" id="annotation-toggle" aria-pressed="true">注目説明</button>
      </div>
      <div id="lesson-workspace">
        <aside id="notes-left" aria-label="左の注目説明"></aside>
        <div id="slide-stage"><iframe id="slide-frame" width="1600" height="900" title="${escapeHtml(lesson.title)}のスライド" sandbox="allow-same-origin"></iframe></div>
        <aside id="notes-right" aria-label="右の注目説明"></aside>
        <svg id="annotation-overlay" aria-hidden="true"></svg>
      </div>
      <p id="slide-error" role="status"></p>
    </section>
    <article class="lesson-body">
      <section><h2>この学習で使う前提</h2><ul>${prerequisites}</ul></section>
      <section><h2>スライドから具体的な動作へ</h2>${explanation}</section>
      <section class="exercise"><h2>自分で確かめる</h2><p>${escapeHtml(lesson.exercise.prompt)}</p><details><summary>解説を読む</summary><p>${escapeHtml(lesson.exercise.answer)}</p></details></section>
      <section><h2>この学習の出典</h2>${sources(profile, lesson.sources)}</section>
    </article>
    <nav class="lesson-navigation" aria-label="学習項目の移動">${previous ? `<a href="../${previous.id}/">← ${escapeHtml(previous.title)}</a>` : "<span></span>"}${next ? `<a href="../${next.id}/">${escapeHtml(next.title)} →</a>` : `<a href="../">学習一覧へ戻る</a>`}</nav>
  </main>
  <script id="learning-data" type="application/json">${data}</script>
  <script type="module" src="../assets/learning.mjs"></script>`,
    "../",
  );
}

/** @param {Profile} profile @returns {string} 対象別スキルを入力から再現可能に生成する。 */
export function renderSkill(profile) {
  return `---
name: learn-${profile.id}
description: ${JSON.stringify(`${profile.technology} ${profile.version}を、${profile.goal}ために体系的に学ぶHTML教材を作成・更新する。対象の学習、教材追加、例の説明、資料更新の依頼で使う。`)}
---

# ${profile.technology}を体系的に学ぶ

到達目標：${profile.goal}
対象読者：${profile.audience}

このファイルはprofileからの生成物である。対象版と資料の正本は [profile.json](references/profile.json)、資料URLは [sources.md](references/sources.md)、取得と更新は [workflow.md](references/workflow.md) に置く。

1. workflow.mdを読み、登録された公式資料を実際に取得する。取得できた本文と対象版だけを根拠にし、未取得は確認済みと書かない。
2. 入力のprofileと同じidを持つコースディレクトリを利用先で特定する。候補が複数あれば依頼の対象を確定する。
3. profile.curriculumの前提と順序に従い、1学習項目1到達目標で作る。既に分かっている目標や前提を聞き直さない。
4. 兄弟のlearning-setupスキルの [教材作成手順](../learning-setup/references/authoring.md) に従い、同梱html-deckを使ってdeckを作る。スライドを短く保ち、前提・流れ・実行例・練習をlesson.jsonへ書く。
5. 注目対象はdata-learning-targetで特定し、左右の説明と対応させる。対象や例を変えたら本文・注目点・出力・出典も照合する。
6. learning-setup/scripts/learning.mjsのcheck/build、html-deckの実測検査、学習ページの表示を確認する。失敗、未実施、人間の確認待ちを分けて報告する。

スライドの制作と実測は兄弟のlearning-setup/vendor/html-deck/SKILL.mdを使う。外側の学習ページはそのスライドHTMLを同一originのiframeに埋め込む。
`;
}

/** @param {Profile} profile @returns {string} */
export function renderSources(profile) {
  return `# ${profile.technology}の公式資料\n\n対象版：${profile.version}。以下の確認日はprofileの入力値であり、この生成コマンドがネットワーク取得したという意味ではない。制作時にはworkflowの取得手順を実行する。\n\n${profile.sources.map((source) => `- **${source.id}** [${source.title}](${source.url}) — ${source.version}、確認日 ${source.checkedAt}`).join("\n")}\n`;
}

/** @param {Profile} profile @returns {string} */
export function renderWorkflow(profile) {
  return `# ${profile.technology}の情報取得と更新\n\n1. sources.mdのURLをWeb取得ツールまたはブラウザで開く。公式host（${profile.officialHosts.join(", ")}）と対象版（${profile.version}）を照合する。\n2. HTMLの外枠だけ、404、アクセス拒否を本文取得成功と扱わない。取得した節と教材に使う主張を対応付ける。取得不能なら別の公式URLを調べ、未取得を記録する。\n3. 言語仕様・API・Getting started・release notesを突き合わせ、前提から各到達目標までの順序をprofile.curriculumで確認する。\n4. codeを実行し、観測した結果と期待だけの結果を区別する。実行できない環境では未実施と明記する。\n5. 更新では同じURLとrelease notesを再取得し、資料の移転・対象版差分・例の変更を確認する。確認できた資料だけcheckedAtを更新する。\n6. profile、lesson.json、deck、注目対象、期待出力を照合してcheck/build/実測をやり直す。最後にsync-skillでこの参照一覧を再生成する。\n\nこれは資料を取得・確認するための手順であり、生成だけで最新情報の確認が済むことを意味しない。\n`;
}

